#!/usr/bin/env node
// Data Cloud DATA GRAPH -> a Diagramforce Data Model diagram.
//
// A thin CLI wrapper. All the parsing, layout and card authoring lives in `datagraph-convert.js`, which is the
// SAME module the app's paste path uses - so a diagram fetched here and one pasted into Load & Import are
// identical rather than merely similar. (Same arrangement as flow-convert.js; the copy beside this file is
// generated by `npm run package:skill` and asserted identical by dev/tests/skill-package.test.js.)
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parseDataGraph, buildDataGraphDiagram } from './datagraph-convert.js';

const die = (m) => { console.error(m); process.exit(1); };

/** Fetch one graph's DEFINITION. Goes through `sf api request rest`, which reuses the CLI's own auth - no
 *  access token is ever read, printed or written by this script. */
function fetchFromOrg(alias, name, apiVersion) {
  const path = `/services/data/${apiVersion}/ssot/data-graphs/${encodeURIComponent(name)}`;
  const body = execFileSync('sf', ['api', 'request', 'rest', path, '-o', alias],
    { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
  return JSON.parse(body);
}

function main(argv) {
  const args = argv.slice(2);
  const val = (f) => { const i = args.indexOf(f); return i >= 0 ? args[i + 1] : null; };
  const org = val('--org'), name = val('--name'), root = val('--root'), title = val('--title');
  // v64.0 is a floor every current org clears, not a ceiling - the converter reads a FIXED field set, so a
  // newer version adds nothing today. The flag exists for the org where the default is wrong, and because the
  // sibling flow script's own advice is "use the org's latest": `GET /services/data/` lists what an org has.
  const apiVersion = val('--api-version') || 'v64.0';
  const positional = args.filter((a, i) => !a.startsWith('--') && !String(args[i - 1] || '').startsWith('--'));
  const [inPath, outPath] = positional;

  if (!inPath && !(org && name)) {
    die('usage: node scripts/datagraph-to-diagramforce.mjs <datagraph.json> [out.json] [--root <RootObjectName>] [--title T]\n'
      + '       node scripts/datagraph-to-diagramforce.mjs --org <alias> --name <DeveloperName> [out.json] [--api-version vXX.0]\n'
      + '\n'
      + 'Input is EITHER the definition from /services/data/v64.0/ssot/data-graphs/<DeveloperName>\n'
      + 'OR the preview JSON copied out of the Data Cloud UI (Data Graph > Preview).\n'
      + 'List the graphs in an org with:\n'
      + '  sf api request rest /services/data/v64.0/ssot/data-graphs/metadata -o <alias>');
  }

  let doc;
  try {
    doc = org && name ? fetchFromOrg(org, name, apiVersion) : JSON.parse(readFileSync(inPath, 'utf8'));
  } catch (e) { die(`Could not read the data graph: ${e.message}`); }

  let parsed, built;
  try {
    parsed = parseDataGraph(doc, root);
    built = buildDataGraphDiagram(parsed, { title });
  } catch (e) { die(e.message); }

  const target = outPath || (org && name ? `${name}.json` : null);
  const json = JSON.stringify(built.diagram, null, 2);
  if (target) writeFileSync(target, json); else process.stdout.write(json);

  const s = built.stats;
  console.error(`✓ ${built.diagram.title}`);
  console.error(`  objects ${s.objects} · links ${s.links} · depth ${s.depth} · from the ${s.kind}`);
  if (s.kind === 'preview') {
    console.error('  note: a PREVIEW payload carries no object labels, field labels or key flags - the names are '
      + 'derived from the API names and the keys from naming convention. Fetch the definition '
      + '(--org <alias> --name <DeveloperName>) for the real ones.');
  }
}

if (import.meta.url === `file://${process.argv[1]}`) main(process.argv);
